{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.03,
  "summary": [
    "Current credible polls place CDU and Greens ahead of AfD in Baden-Württemberg, making AfD unlikely to lead the seat tally.",
    "Historical precedent shows AfD has never won the most seats in BW; Greens or CDU have led in recent cycles.",
    "Poll ranges circa late 2025 to early 2026 place AfD around 18–21%, well behind the top two blocs.",
    "A Bayesian update with these factors yields a posterior of about 1%, reflecting the reference-class dominance of CDU/Greens over AfD."
  ],
  "confidence": "low",
  "narrative": "Anchoring on the BW reference class, then downgrading AfD's prospects based on recent polls and history, the analysis yields a near-zero probability of AfD winning the most seats. Despite occasional momentum signals, the prevailing evidence keeps AfD well behind the leading parties.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Baseline anchor from BW Landtag history: Greens/CDU typically lead; AfD has not led seat counts in BW to date."
    },
    "factor_updates": [
      {
        "factor": "CDU leads in latest pre-election polls",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Infratest dimap-style results show CDU ahead of Greens and AfD, constraining AfD's path to the top."
      },
      {
        "factor": "AfD polling around 18–21% across major surveys",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "AfD remains behind the top two parties by a comfortable margin in multiple credible polls."
      },
      {
        "factor": "Historical precedent: AfD has never won the most seats in BW",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Past results (e.g., 2021 Greens 32.6%; AfD 9.7%) set a durable base rate against AfD topping BW."
      },
      {
        "factor": "BWTrend/occasional AfD lead signals",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Some polls show brief AfD momentum; not sustained enough to overturn the baseline."
      },
      {
        "factor": "Polymarket/AI consensus places AfD around 18–21%",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Non-traditional forecasts align with AfD not leading the field; greens near CDU in many measures, limiting AfD upside."
      }
    ],
    "synthesis_rationale": "The anchor probability was modestly reduced by strong downward updates from current polling and historical precedent; a small upward factor from brief AfD momentum signals and some AI/Polymarket readings was not sufficient to overcome the baseline. Given correlation among polls and factors, the calibrated posterior settles at 1% with a narrow confidence interval."
  }
}

